def get_full_120_scenario_catalogue() -> List[Dict[str, Any]]:
    """Returns the structured 120-scenario validation catalogue with full test metadata."""
    catalogue = []
    for idx, spec in enumerate(RAW_SCENARIO_SPECS, start=1):
        (
            code,
            category,
            title,
            stage_num,
            stage_name,
            severity,
            supports_advance_prediction,
            supports_fault_detection,
            attribution_type,
            expected_diagnosis,
            recovery_procedure,
            applicable_modes,
        ) = spec
        catalogue.append({
            "index": idx,
            "scenario_id": code,
            "category": category,
            "title": title,
            "primary_stage_number": stage_num,
            "primary_stage_name": stage_name,
            "severity": severity,
            "supports_advance_prediction": supports_advance_prediction,
            "supports_fault_detection": supports_fault_detection,
            "expected_prediction_classification": "ADVANCE_PREDICTION" if supports_advance_prediction else "ACTIVE_FAILURE_DETECTION",
            "expected_attribution_type": attribution_type,
            "expected_diagnosis": expected_diagnosis,
            "recovery_procedure": recovery_procedure,
            "applicable_behavior_modes": applicable_modes,
            "test_objective": f"Validate detection, {'advance prediction & early warning, ' if supports_advance_prediction else ''}stage-{stage_num} localization ({stage_name}), {attribution_type} attribution, and clean recovery for {code} ({title}).",
            "isolated_setup": f"Isolated virtual test harness injecting controlled {code} fault signature at Stage {stage_num} ({stage_name}) without production disruption.",
        })
    return catalogue


SCENARIO_BY_CODE: Dict[str, Dict[str, Any]] = {
    item["scenario_id"]: item for item in get_full_120_scenario_catalogue()
}
